solution.code:
function double(value: number): number {
  return value * 2;
}

console.log(double(5));
// console.log(double('5')); // now a COMPILE error — caught!

function formatCurrency(amount: number, code: string): string {
  return code + ' ' + amount.toFixed(2);
}

console.log(formatCurrency(1234.5, 'USD'));
console.log(formatCurrency(8, 'EUR'));
